def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    fixed_high = 0
    low_competitors = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= 100:
                    fixed_high += 1
                if float(bid) <= 20:
                    low_competitors += 1

    if not alive_opponents:
        return float(min(budget, 10))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    positive_prev = [b for b in prev_bids if b > 0]
    low_anchor = min(positive_prev) if positive_prev else 15.0

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1

    if supply <= WATER_REQ:
        urgency += 2
    elif supply <= WATER_REQ + 3:
        urgency += 1

    if day >= 8:
        urgency += 1

    affordable_safe = min(budget, DAILY_SALARY * 0.95)
    affordable_mid = min(budget, DAILY_SALARY * 0.55)

    if urgency >= 5:
        bid = affordable_safe
    elif urgency >= 3:
        bid = min(budget, max(30.0, low_anchor + 3.0, min(55.0, highest_prev + 1.0 if highest_prev < 60 else 45.0)))
    else:
        if fixed_high >= 1 and hp > 4 and no_water_days == 0:
            bid = min(budget, max(12.0, low_anchor + 1.0))
        elif highest_prev <= 20:
            bid = min(budget, max(16.0, highest_prev + 1.0))
        else:
            bid = affordable_mid

    if budget < 20:
        bid = min(bid, budget)

    if hp <= 3 and bid < 40:
        bid = min(budget, 40.0)

    if supply >= 22 and urgency <= 1:
        bid = min(bid, 18.0)

    return float(max(0.0, min(budget, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents and yesterday bids
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        # No contest; bid modestly
        return max(0.0, min(my_status['budget'], DAILY_SALARY * 0.4))

    yesterday_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Estimate aggressiveness from yesterday
    if yesterday_bids:
        highest_prev = max(yesterday_bids)
        avg_prev = sum(yesterday_bids) / float(len(yesterday_bids))
    else:
        highest_prev = 0.0
        avg_prev = 0.0

    # Base target: aim to win without matching Cindy's extreme behavior.
    # If someone previously bid very high, we slightly back off and rely on not overpaying.
    # If bids were generally low, we bid enough to secure.
    # Also incorporate my hp: lower hp => more aggressive to avoid death.
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])

    # Supply-aware heuristic: more supply reduces need to overbid.
    # Normalize supply into [0,1]
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_norm = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    else:
        supply_norm = 0.5
    supply_norm = max(0.0, min(1.0, supply_norm))

    # Determine aggressiveness factor
    if hp <= 2:
        hp_factor = 0.95
    elif hp <= 4:
        hp_factor = 0.75
    else:
        hp_factor = 0.60

    # Bid level selection
    # If highest_prev is extreme (>= 120), don't chase; use a mid bid.
    if highest_prev >= 120.0:
        base = DAILY_SALARY * (0.35 + 0.15 * (1.0 - supply_norm))
        # If average was also high, increase somewhat
        if avg_prev >= 60.0:
            base *= 1.15
    elif highest_prev >= 60.0:
        base = DAILY_SALARY * (0.45 + 0.15 * (1.0 - supply_norm))
    else:
        base = DAILY_SALARY * (0.55 + 0.10 * (1.0 - supply_norm))

    bid = base * hp_factor

    # Ensure we bid at least enough to plausibly secure 1 unit of water requirement.
    # Convert supply to estimated number of water units available.
    # We avoid float indices; this is just a scalar heuristic.
    # Target probability of winning increases with bid but we cap to budget.
    # Use a soft floor based on my water requirement.
    # If supply is low, be more aggressive.
    if supply < WATER_REQ:
        bid *= 1.25

    # Final cap
    bid = max(0.0, min(bid, budget, DAILY_SALARY * 0.9))

    # If budget is extremely low, bid whatever remains
    if budget <= 1.0:
        return max(0.0, budget)

    # If bidding too low could guarantee no water, enforce a minimal bid fraction
    # (still capped by budget)
    min_bid = DAILY_SALARY * 0.25
    if bid < min_bid and budget >= min_bid:
        bid = min_bid

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MY_HP = my_status['hp']
    MY_BUDGET = my_status['budget']
    SUPPLY = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(MY_BUDGET, WATER_REQ * 1.05)

    yesterday_bids = []
    total_water_needed_by_opponents = 0
    for opp in alive_opponents:
        total_water_needed_by_opponents += opp['water_requirement']
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    total_water_needed_including_me = WATER_REQ + total_water_needed_by_opponents

    bid = WATER_REQ * 1.05 

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if SUPPLY < total_water_needed_including_me:
            if MY_HP <= 3:
                bid = max(bid, highest_prev_bid + 5, DAILY_SALARY * 0.9)
            else:
                bid = max(bid, highest_prev_bid + 2)
        else:
            if highest_prev_bid > bid:
                bid = max(bid, highest_prev_bid + 1)
            if MY_HP <= 2:
                bid = max(bid, DAILY_SALARY * 0.8)

    if MY_HP <= 1:
        bid = DAILY_SALARY * 0.99
    elif my_status['no_water_days'] > 0:
        bid = max(bid, DAILY_SALARY * 0.85)

    bid = min(bid, MY_BUDGET)
    bid = max(1.0, bid)

    if MY_HP > 1:
        bid = min(bid, DAILY_SALARY)

    return bid

